  select distinct on (doc_number, check_in)
    source_row, id, ha, name, nationality, nationality_code, birth_date, birth_place, doc_number, doc_type, issuer_country, issuer_country_code, residence_country, residence_country_code, residence_city, check_in, check_out, sent_status, sent_at, send_error, send_batch_number, created_at, updated_at
